"""INEP Indicadores Educacionais catalog.

18 indicadores derivados (não microdados brutos), publicados em
gov.br/inep/.../dados-abertos/indicadores-educacionais. Cada indicador tem uma
aba por ano (ou por período, para os indicadores de educação superior) que só
carrega via fragmento AJAX (``data-url`` da aba) — os links reais NÃO aparecem
na página estática. Todas as 650 URLs abaixo foram obtidas ao vivo buscando
cada fragmento individualmente (2026-07-24) e são literais: a nomenclatura muda
de era dentro de quase todo indicador (ex.: prefixos em maiúsculas tipo AFD/TDI/
ICG a partir de ~2022 vs. nomes descritivos em português em anos anteriores),
então não há fórmula/range() confiável — mesmo padrão de irregularidade já visto
em SAEB/ENADE, mas em escala maior (18 indicadores x até 20 anos cada).

``year`` é sempre ``None`` nesses dados: o nome de arquivo público já embute o
período (que por sua vez varia entre ano único, ex. "2025", e intervalo, ex.
"2010-2024", dependendo do indicador) — usar um ``base_id`` derivado do nome
real do arquivo evita ambiguidade e mantém cada entrada única por construção.
"""

from ._catalog_base import DatasetEntry, GroupInfo

_SOURCE = "inep-indicadores-educacionais"

